//! Compares the built-in `tailwind` class order with Tailwind CSS itself.
//!
//! `tests/class-order/tailwind.tsv` holds random class lists and the order
//! Tailwind's compiler gives them (as `prettier-plugin-tailwindcss` and
//! `eslint-plugin-tailwindcss` apply it). Both files are generated by
//! `scripts/generate-tailwind-order.mjs`.

use annealer::{ClassOrder, Config, Language, format};

/// Sorts a class list through the public API, as a `class` attribute.
fn sort(config: &Config, classes: &str) -> String {
    let output = format(&format!("<p class=\"{classes}\">"), config).unwrap();
    output["<p class=\"".len()..output.len() - "\">".len()].to_owned()
}

#[test]
fn matches_tailwind_on_the_generated_corpus() {
    let config =
        Config::for_language(Language::Html).with_class_order(ClassOrder::builtin("tailwind"));
    let corpus = include_str!("class-order/tailwind.tsv");
    let mut mismatches = Vec::new();
    let mut total = 0;
    for line in corpus.lines() {
        let (input, expected) = line.split_once('\t').unwrap();
        total += 1;
        let actual = sort(&config, input);
        if actual != expected {
            mismatches.push(format!(
                "  input:    {input}\n  expected: {expected}\n  actual:   {actual}"
            ));
        }
    }
    assert!(
        mismatches.is_empty(),
        "{} of {total} lists differ from Tailwind:\n{}",
        mismatches.len(),
        mismatches
            .iter()
            .take(15)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n\n")
    );
}
